// Polyfill brotli for CompressionStream/DecompressionStream on runtimes that
// don't natively support 'br' (e.g. Node.js < 22.7). Other formats are delegated
// to the original implementations.
const OriginalCompressionStream = globalThis.CompressionStream
const OriginalDecompressionStream = globalThis.DecompressionStream
class PolyfilledCompressionStream {
  readable: ReadableStream
  writable: WritableStream
  constructor(format: string) {
    if (format === 'br') {
      const web = Duplex.toWeb(createBrotliCompress())
      this.readable = web.readable as ReadableStream
      this.writable = web.writable as WritableStream
      return
    }
    const real = new OriginalCompressionStream(format as 'gzip')
    this.readable = real.readable
    this.writable = real.writable
